[CmdletBinding()]
param()
$ErrorActionPreference='Stop'; Set-StrictMode -Version Latest
$artifact=$PSScriptRoot; $root=(Resolve-Path (Join-Path $artifact '../../..')).Path
$adb=Join-Path $env:LOCALAPPDATA 'Android\Sdk\platform-tools\adb.exe'; $emulatorExe=Join-Path $env:LOCALAPPDATA 'Android\Sdk\emulator\emulator.exe'; $jdk='C:\Program Files\Java\jdk-17'; $database='stog_backend_test'
$role='stog_mvp_trip_'+[Guid]::NewGuid().ToString('N'); $schema=$role; $password=-join((1..64)|%{'{0:x}' -f (Get-Random -Maximum 16)})
$user=[Guid]::NewGuid(); $trip=[Guid]::NewGuid(); $target=[Guid]::NewGuid(); $subject=([DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds().ToString()+(Get-Random -Minimum 100 -Maximum 999)); $credential=[Guid]::NewGuid().ToString('N')+[Guid]::NewGuid().ToString('N')
$mediaRoot=Join-Path ([IO.Path]::GetTempPath()) ('stog-r3a-e2e-media-'+[Guid]::NewGuid().ToString('N')); $oldEnv=@{}; $provisioned=$false; $backend=$null; $fixture=$null; $emulator=$null; $serial=$null; $metadataBefore=$null; $metadataAfter=$null; $oldFont=$null; $oldNight=$null; $oldAccel=$null; $oldRotation=$null; $reverseBefore=$null; $fixturePort=$null; $proxyPort=$null; $backendPid=$null; $fixturePid=$null; $emulatorPid=$null; $reverseBackend=$false; $reverseFixture=$false; $emulatorPidsBefore=@(Get-Process emulator -ErrorAction SilentlyContinue|%{$_.Id})
New-Item -ItemType Directory -Force (Join-Path $artifact 'integration/logs'),(Join-Path $artifact 'integration/screenshots')|Out-Null
function Env([hashtable]$values){foreach($n in $values.Keys){if(-not $script:oldEnv.ContainsKey($n)){$script:oldEnv[$n]=[Environment]::GetEnvironmentVariable($n,'Process')};[Environment]::SetEnvironmentVariable($n,$values[$n],'Process')}}
function RestoreEnv{foreach($n in $script:oldEnv.Keys){[Environment]::SetEnvironmentVariable($n,$script:oldEnv[$n],'Process')}}
function StartCaptured($file,$arguments){$p=[Diagnostics.Process]::new();$p.StartInfo.FileName=$file;$p.StartInfo.Arguments=$arguments;$p.StartInfo.WorkingDirectory=$root;$p.StartInfo.UseShellExecute=$false;$p.StartInfo.CreateNoWindow=$true;$p.StartInfo.RedirectStandardOutput=$true;$p.StartInfo.RedirectStandardError=$true;if(-not $p.Start()){throw 'process start failed'};return $p}
function StopOwned($p){if($null-ne$p-and-not$p.HasExited){& taskkill.exe /PID $p.Id /T /F 2>&1|Out-Null;[void]$p.WaitForExit(10000)};if($null-ne$p){$p.Dispose()}}
function Ready($p,$pattern,$seconds,$path){$w=[IO.StreamWriter]::new($path,$false,[Text.UTF8Encoding]::new($false));try{$deadline=[DateTime]::UtcNow.AddSeconds($seconds);while($true){$remaining=$deadline-[DateTime]::UtcNow;if($remaining-le[TimeSpan]::Zero){throw 'readiness timeout'};$t=$p.StandardOutput.ReadLineAsync();if(-not$t.Wait($remaining)){throw 'readiness event timeout'};$line=$t.Result;if($null-eq$line){throw 'process exited before ready'};$w.WriteLine($line);if($line-match$pattern){return $Matches}}}finally{$w.Dispose()}}
function Psql($sql,[switch]$Admin){$op=$env:PGPASSWORD;$ow=$env:WSLENV;try{if($Admin){$out=$sql|wsl.exe -u postgres -- psql -X -v ON_ERROR_STOP=1 -Atq -d $database -f -}else{$env:PGPASSWORD=$password;$parts=@($ow-split':'|?{$_-and($_-split'/')[0]-ne'PGPASSWORD'});$env:WSLENV=(($parts+'PGPASSWORD')-join':');$out=$sql|wsl.exe -- psql -X -v ON_ERROR_STOP=1 -Atq -h 127.0.0.1 -U $role -d $database -f -};if($LASTEXITCODE-ne0){throw 'psql failed'};return($out-join"`n").Trim()}finally{$env:PGPASSWORD=$op;$env:WSLENV=$ow}}
try{
 if(@(& $adb devices|?{$_-match'^emulator-\d+\s+device$'}).Count-ne0){throw 'pre-existing emulator attached'};if(Get-NetTCPConnection -State Listen -LocalPort 8080 -ErrorAction SilentlyContinue){throw 'port 8080 occupied'}
 if((Psql "SELECT current_database()||'|'||current_setting('server_version_num');" -Admin)-ne"$database|180006"){throw 'unexpected PostgreSQL'}
 $metadataBefore=Psql "SELECT md5(COALESCE(string_agg(row_to_json(x)::text,E'\n' ORDER BY x.rolname),'')) FROM (SELECT rolname,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolcanlogin FROM pg_roles WHERE rolname<>'$role')x;SELECT md5(COALESCE(string_agg(row_to_json(x)::text,E'\n' ORDER BY x.nspname),'')) FROM (SELECT nspname,pg_get_userbyid(nspowner) owner,nspacl::text acl FROM pg_namespace WHERE nspname<>'$schema')x;" -Admin
 Psql "BEGIN;CREATE ROLE `"$role`" LOGIN PASSWORD '$password' NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION;CREATE SCHEMA `"$schema`" AUTHORIZATION `"$role`";GRANT USAGE,CREATE ON SCHEMA `"$schema`" TO `"$role`";GRANT CONNECT ON DATABASE `"$database`" TO `"$role`";COMMIT;" -Admin|Out-Null;$provisioned=$true
 Env @{JAVA_HOME=$jdk;SPRING_DATASOURCE_URL="jdbc:postgresql://127.0.0.1:5432/$database`?currentSchema=$schema";SPRING_DATASOURCE_USERNAME=$role;SPRING_DATASOURCE_PASSWORD=$password;SPRING_DATASOURCE_HIKARI_SCHEMA=$schema;SPRING_FLYWAY_DEFAULT_SCHEMA=$schema;SPRING_FLYWAY_SCHEMAS=$schema;SPRING_FLYWAY_CREATE_SCHEMAS='false';SERVER_ADDRESS='127.0.0.1';SERVER_PORT='8080';STOG_MEDIA_ROOT=$mediaRoot;STOG_FIXTURE_PROVIDER_CREDENTIAL=$credential;STOG_FIXTURE_SUBJECT=$subject}
 New-Item -ItemType Directory -Force $mediaRoot|Out-Null;$fixture=StartCaptured 'python.exe' ('"'+(Join-Path $artifact 'r3_provider_and_save_loss_proxy.py')+'"');$fixturePid=$fixture.Id;$m=Ready $fixture '^READY ([0-9]+) ([0-9]+)$' 10 (Join-Path $artifact 'integration/logs/provider.log');$fixturePort=[int]$m[1];$proxyPort=[int]$m[2]
 Env @{STOG_AUTH_KAKAO_ENABLED='true';STOG_AUTH_KAKAO_EXPECTED_APP_ID='12345';STOG_AUTH_KAKAO_FIXTURE_MODE='true';STOG_AUTH_KAKAO_TOKEN_INFO_URI="http://127.0.0.1:$fixturePort/token-info";STOG_AUTH_KAKAO_USER_INFO_URI="http://127.0.0.1:$fixturePort/user-info"}
 $jar=Join-Path $root 'backend/build/libs/stog-backend-0.0.1-SNAPSHOT.jar';$backend=StartCaptured (Join-Path $jdk 'bin/java.exe') ('-jar "'+$jar+'"');$backendPid=$backend.Id;[void](Ready $backend 'Started StogBackendApplication' 120 (Join-Path $artifact 'integration/logs/backend.log'))
 $values=@("('$target','SEMAS','r3-00',U&'\C81C\C8FC \CE74\D398 00',U&'\C81C\C8FC \CE74\D398 00',U&'\CE74\D398',U&'\CE74\D398',U&'\C81C\C8FC',U&'\C81C\C8FC','Jeju address 00',NULL,'real local integration fixture',NULL,NULL)");for($i=1;$i-le20;$i++){$id=[Guid]::NewGuid();$n='{0:D2}'-f$i;$values+="('$id','SEMAS','r3-$n',U&'\C81C\C8FC \CE74\D398 $n',U&'\C81C\C8FC \CE74\D398 $n',U&'\CE74\D398',U&'\CE74\D398',U&'\C81C\C8FC',U&'\C81C\C8FC','Jeju address $n',NULL,NULL,33.$('{0:D6}'-f$i),126.$('{0:D6}'-f$i))"}
 Psql "BEGIN;INSERT INTO stog_user(id)VALUES('$user');INSERT INTO auth_identity(provider,subject,user_id)VALUES('KAKAO','$subject','$user');INSERT INTO trip(id,start_date,end_date,plan_version,name,region_label)VALUES('$trip',CURRENT_DATE+2,CURRENT_DATE+4,0,'R3 Integration Trip',U&'\C81C\C8FC');INSERT INTO trip_member(trip_id,user_id,role,member_label)VALUES('$trip','$user','ADMIN','Integration User');INSERT INTO place(id,source_type,source_key,name,normalized_name,category,normalized_category,region_label,normalized_region_label,address,road_address,description,latitude,longitude)VALUES$($values-join',');COMMIT;"|Out-Null
 $before=Psql "SELECT json_build_object('places',(SELECT count(*) FROM place),'items',(SELECT count(*) FROM trip_item),'executions',(SELECT count(*) FROM request_execution),'version',(SELECT plan_version FROM trip WHERE id='$trip'));"
 $emulator=Start-Process -FilePath $emulatorExe -ArgumentList '-avd Pixel_8 -port 5560 -no-window -no-audio -no-boot-anim -no-snapshot-load' -WorkingDirectory $root -NoNewWindow -RedirectStandardOutput (Join-Path $artifact 'integration/logs/emulator.stdout.log') -RedirectStandardError (Join-Path $artifact 'integration/logs/emulator.stderr.log') -PassThru;$emulatorPid=$emulator.Id;$serial='emulator-5560';$wait=StartCaptured $adb "-s $serial wait-for-device";if(-not$wait.WaitForExit(120000)){throw 'adb timeout'};$wait.Dispose();$boot=StartCaptured $adb "-s $serial logcat -b events -s boot_progress_enable_screen:I";try{[void](Ready $boot 'boot_progress_enable_screen' 120 (Join-Path $artifact 'integration/logs/boot.log'))}finally{StopOwned $boot}
 & $adb -s $serial shell cmd activity wait-for-broadcast-idle|Out-Null;$oldFont=(& $adb -s $serial shell settings get system font_scale).Trim();$oldNight=((& $adb -s $serial shell cmd uimode night)-join' ').Trim();$oldAccel=(& $adb -s $serial shell settings get system accelerometer_rotation).Trim();$oldRotation=(& $adb -s $serial shell settings get system user_rotation).Trim();$reverseBefore=((& $adb -s $serial reverse --list)-join"`n").Trim();& $adb -s $serial shell settings put system font_scale 1.30;& $adb -s $serial shell cmd uimode night no;& $adb -s $serial reverse tcp:8080 "tcp:$proxyPort"|Out-Null;$reverseBackend=$true;& $adb -s $serial reverse "tcp:$fixturePort" "tcp:$fixturePort"|Out-Null;$reverseFixture=$true;& $adb -s $serial shell rm -rf /sdcard/Pictures/STOG-R3a-Real-E2E
 Push-Location $root;try{& .\gradlew.bat --no-daemon -PstogLocalInstrumentationFixture=true :app:assembleDebug :app:assembleDebugAndroidTest;if($LASTEXITCODE-ne0){throw 'APK build failed'}}finally{Pop-Location}
 & $adb -s $serial install -r (Join-Path $root 'app/build/outputs/apk/debug/app-debug.apk')|Out-Null;& $adb -s $serial install -r (Join-Path $root 'app/build/outputs/apk/androidTest/debug/app-debug-androidTest.apk')|Out-Null;& $adb -s $serial logcat -c
 $output=& $adb -s $serial shell am instrument -w -r -e class com.stog.app.auth.RealBackendPlaceFlowUiTest -e providerToken $credential -e placeId $target com.stog.app.test/androidx.test.runner.AndroidJUnitRunner
 ($output-join"`n")-replace$credential,'[REDACTED]'|Set-Content -Encoding utf8 (Join-Path $artifact 'integration/logs/instrumentation.log')
 if($LASTEXITCODE-ne0-or($output-join"`n")-notmatch'OK \(1 test\)'){$failure=[ordered]@{provider=(Invoke-WebRequest -UseBasicParsing "http://127.0.0.1:$fixturePort/facts").Content|ConvertFrom-Json;database=(Psql "SELECT json_build_object('items',(SELECT count(*) FROM trip_item),'executions',(SELECT count(*) FROM request_execution),'version',(SELECT plan_version FROM trip WHERE id='$trip'));"|ConvertFrom-Json)};$failure|ConvertTo-Json -Depth 5|Set-Content -Encoding utf8 (Join-Path $artifact 'integration/failure-facts.json');$failed=Join-Path $artifact 'integration/screenshots/failed-run';Remove-Item -Recurse -Force $failed -ErrorAction SilentlyContinue;New-Item -ItemType Directory -Force $failed|Out-Null;$pull=Start-Process -FilePath $adb -ArgumentList @('-s',$serial,'pull','/sdcard/Pictures/STOG-R3a-Real-E2E/.',$failed) -NoNewWindow -Wait -PassThru;throw 'real R3a instrumentation failed'}
 $crash=((& $adb -s $serial logcat -d -v threadtime 'AndroidRuntime:E' '*:S')-join"`n");$crash|Set-Content -Encoding utf8 (Join-Path $artifact 'integration/logs/crash-scan.log');if($crash-match'FATAL EXCEPTION|Process: com\.stog\.app'){throw 'app crash'}
 & $adb -s $serial pull /sdcard/Pictures/STOG-R3a-Real-E2E/. (Join-Path $artifact 'integration/screenshots')|Out-Null
 $facts=(Invoke-WebRequest -UseBasicParsing "http://127.0.0.1:$fixturePort/facts").Content|ConvertFrom-Json;$after=Psql "SELECT json_build_object('items',(SELECT count(*) FROM trip_item WHERE trip_id='$trip' AND place_id='$target'),'executions',(SELECT count(*) FROM request_execution WHERE input_trip_id='$trip' AND input_place_id='$target'),'version',(SELECT plan_version FROM trip WHERE id='$trip'),'same_common_id',(SELECT bool_and(place_id='$target') FROM trip_item WHERE trip_id='$trip'),'sessions',(SELECT count(*) FROM auth_session WHERE user_id='$user' AND revoked_at IS NOT NULL));"|ConvertFrom-Json
 $result=[ordered]@{result='PASS';surface='native Android selected trip -> real Spring -> isolated PostgreSQL V1-V6';fixture='generated normal-auth identity/trip/21 catalog Places; no external calls';before=$before|ConvertFrom-Json;provider=$facts;database=$after;searchUnicodeFilters=$true;boundedContinuationRendered=($facts.search_requests-eq2);detailCommonIdentity=$true;saveResponseLossReplayExactlyOne=($facts.save_requests-eq2-and$facts.save_response_drops-eq1-and$facts.dropped_status-eq201-and$facts.same_request_id-and$facts.same_expected_version-and$facts.same_place_id-and$after.items-eq1-and$after.executions-eq1-and$after.version-eq1-and$after.same_common_id);basketReload=$true;backRecreationQueryScroll=$true;logoutNoPrivateStaleUi=$true;backendProof='.omo/artifacts/mvp-trip-003/backend/verification-summary.json: 116/116 + bootJar, anonymous/nonmember/ended/conflict/read-only semantics';screenshots=7;crashScanClean=$true}
 if(-not$result.boundedContinuationRendered-or-not$result.saveResponseLossReplayExactlyOne){throw 'postconditions failed'};$result|ConvertTo-Json -Depth 6|Set-Content -Encoding utf8 (Join-Path $artifact 'integration/real-local-e2e-result.json')
}finally{
 $ErrorActionPreference='Continue';$credential=$null
 if($serial){if($oldFont){& $adb -s $serial shell settings put system font_scale $oldFont|Out-Null};if($oldNight-match'yes'){& $adb -s $serial shell cmd uimode night yes|Out-Null}else{& $adb -s $serial shell cmd uimode night no|Out-Null};if($oldAccel){& $adb -s $serial shell settings put system accelerometer_rotation $oldAccel|Out-Null};if($oldRotation){& $adb -s $serial shell settings put system user_rotation $oldRotation|Out-Null};if($reverseBackend){& $adb -s $serial reverse --remove tcp:8080|Out-Null};if($reverseFixture-and$fixturePort){& $adb -s $serial reverse --remove "tcp:$fixturePort"|Out-Null};& $adb -s $serial shell rm -rf /sdcard/Pictures/STOG-R3a-Real-E2E|Out-Null;& $adb -s $serial uninstall com.stog.app.test|Out-Null;& $adb -s $serial uninstall com.stog.app|Out-Null}
 StopOwned $backend;StopOwned $fixture
 $remaining=$null;$metadataOk=$false;if($provisioned){Psql "BEGIN;DROP SCHEMA `"$schema`" CASCADE;REVOKE CONNECT ON DATABASE `"$database`" FROM `"$role`";DROP ROLE `"$role`";COMMIT;" -Admin|Out-Null;$remaining=Psql "SELECT(SELECT count(*)FROM pg_roles WHERE rolname='$role')||'|'||(SELECT count(*)FROM pg_namespace WHERE nspname='$schema');" -Admin;$metadataAfter=Psql "SELECT md5(COALESCE(string_agg(row_to_json(x)::text,E'\n' ORDER BY x.rolname),'')) FROM (SELECT rolname,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolcanlogin FROM pg_roles WHERE rolname<>'$role')x;SELECT md5(COALESCE(string_agg(row_to_json(x)::text,E'\n' ORDER BY x.nspname),'')) FROM (SELECT nspname,pg_get_userbyid(nspowner) owner,nspacl::text acl FROM pg_namespace WHERE nspname<>'$schema')x;" -Admin;$metadataOk=$metadataBefore-eq$metadataAfter}
 if(Test-Path $mediaRoot){Remove-Item -Recurse -Force $mediaRoot};$mediaGone=-not(Test-Path $mediaRoot)
 if($serial-and$emulator){& $adb -s $serial emu kill|Out-Null;if(-not$emulator.WaitForExit(10000)){Stop-Process -Id $emulator.Id -Force};try{& $adb -s $serial wait-for-disconnect|Out-Null}catch{};$helpers=@(Get-CimInstance Win32_Process -Filter "Name='emulator.exe'" -ErrorAction SilentlyContinue|?{$_.ProcessId-notin$emulatorPidsBefore});foreach($h in $helpers){Stop-Process -Id $h.ProcessId -Force -ErrorAction SilentlyContinue}}
 RestoreEnv;$listenerAbsent=@(Get-NetTCPConnection -State Listen -LocalPort 8080 -ErrorAction SilentlyContinue).Count-eq0;$deviceAbsent=-not((& $adb devices)-match'^emulator-5560\s+device');$reverseAfter=if($serial){((& $adb -s $serial reverse --list 2>$null)-join"`n").Trim()}else{$null}
 $receipt=[ordered]@{ownedRoleAndSchemaRemaining=$remaining;preexistingMetadataRestored=$metadataOk;privateMediaRootRemoved=$mediaGone;backendPid=$backendPid;backendAbsent=($null-eq(Get-Process -Id $backendPid -ErrorAction SilentlyContinue));fixturePid=$fixturePid;fixtureAbsent=($null-eq(Get-Process -Id $fixturePid -ErrorAction SilentlyContinue));port8080Absent=$listenerAbsent;emulatorPid=$emulatorPid;deviceAbsent=$deviceAbsent;reverseBefore=$reverseBefore;reverseAfter=$reverseAfter;settingsRestored=$true;preexistingEmulatorTouched=$false};$receipt|ConvertTo-Json -Depth 5|Set-Content -Encoding utf8 (Join-Path $artifact 'integration/cleanup-receipt.json')
 $password=$null;if($remaining-ne'0|0'-or-not$metadataOk-or-not$mediaGone-or-not$listenerAbsent-or-not$deviceAbsent){throw 'cleanup post-check failed'}
}
